import { checkRegistry } from '@app/contracts';
import {
  createRoleAuthorizer,
  createTestContext,
  createTestExecutor,
  createTestPrincipal,
  denyAllAuthorizer,
  type TestExecutor,
} from '@app/kernel';
import { describe, expect, it } from 'vitest';

import { createSubject, sampleInput } from './topology-graph.fixture';
import { topologyGraph } from '@app/contracts';
import { createTopologyGraphAction } from './topology-graph';
import { runQuery, type FakeOptions } from './run.fixture';
import { SAMPLE_VHOST, type FakeVhost } from '../testing';

const subject = createSubject;
const { def } = createSubject();
const KEY = 'generated-spec-key-0001';

/** Runs the action as the engine does: a plan first when one is required, then its execution. */
async function runToEnd(engine: TestExecutor) {
  const ctx = createTestContext({ idempotencyKey: KEY });
  const outcome = await engine.executor.run(def, sampleInput, ctx);
  if (outcome.kind !== 'planRequired') return outcome;
  return engine.executor.execute(
    {
      planId: outcome.plan.id,
      consents: [...outcome.plan.consentsRequired],
      confirmation: outcome.plan.confirmationPhrase,
      idempotencyKey: KEY,
    },
    ctx,
  );
}

describe('topology.graph', () => {
  it('M1-20 G-1 the contract passes the kit invariants and the sample input fits it', () => {
    expect(checkRegistry({ actions: [def], topics: [] })).toEqual([]);
    expect(def.input.safeParse(sampleInput).success).toBe(true);
  });

  it('M1-20 G-3 a principal that does not hold broker.read is refused before anything runs', async () => {
    const engine = createTestExecutor({
      executor: {
        authorizer: createRoleAuthorizer({ operator: ['broker.read'] }),
      },
    });
    engine.executor.register(subject());
    const ctx = createTestContext({
      principal: createTestPrincipal({ roles: ['intruder'] }),
      idempotencyKey: KEY,
    });

    await expect(
      engine.executor.run(def, sampleInput, ctx),
    ).rejects.toMatchObject({ code: 'FORBIDDEN_RBAC' });

    expect(engine.audit.attempts).toEqual([]);
    expect(engine.receipts.records).toEqual([]);
    expect(engine.writeCalls).toEqual([]);
  });

  it('M1-20 G-3 with no authorizer wired every call is refused: deny by default', async () => {
    const engine = createTestExecutor({
      executor: { authorizer: denyAllAuthorizer },
    });
    engine.executor.register(subject());

    await expect(runToEnd(engine)).rejects.toMatchObject({
      code: 'FORBIDDEN_RBAC',
    });

    expect(engine.audit.attempts).toEqual([]);
    expect(engine.writeCalls).toEqual([]);
  });

  it('M1-20 G-3 a principal that holds broker.read is let through', async () => {
    const engine = createTestExecutor({
      executor: {
        authorizer: createRoleAuthorizer({ operator: ['broker.read'] }),
      },
    });
    engine.executor.register(subject());
    const ctx = createTestContext({
      principal: createTestPrincipal({ roles: ['operator'] }),
      idempotencyKey: KEY,
    });

    const outcome = await engine.executor.run(def, sampleInput, ctx);

    expect(['output', 'job', 'planRequired']).toContain(outcome.kind);
  });

  it('M1-20 G-4 a query leaves no audit row and no receipt, and answers in the shape of the contract', async () => {
    const engine = createTestExecutor();
    engine.executor.register(subject());

    const done = await runToEnd(engine);

    if (done.kind !== 'output')
      throw new Error(`expected output, got ${done.kind}`);
    expect(def.output.safeParse(done.output).success).toBe(true);
    expect(engine.audit.attempts).toEqual([]);
    expect(engine.receipts.records).toEqual([]);
  });
});

// --- M1-20 -------------------------------------------------------------------------------------
const answerOf = (
  input: Record<string, unknown>,
  vhosts: Record<string, FakeVhost>,
  options: FakeOptions = {},
) =>
  runQuery(topologyGraph, createTopologyGraphAction, input, {
    ...options,
    vhosts,
  });

describe('M1-20 AC-2 graph is whole when it fits and aggregated when it does not', () => {
  it('draws the bindings and the dead-letter link of a small vhost, with nothing folded', async () => {
    const { output } = await answerOf({ vhost: '/' }, { '/': SAMPLE_VHOST });
    const { graph } = output;

    expect(graph.nodes.map((n) => n.id)).toEqual([
      'x:orders',
      'x:orders.dlx',
      'q:orders.dlq',
      'q:orders.q',
    ]);
    expect(graph.edges.map((e) => [e.kind, e.from, e.to])).toEqual([
      ['dead-letter', 'q:orders.q', 'x:orders.dlx'],
      ['binding', 'x:orders', 'q:orders.q'],
      ['binding', 'x:orders.dlx', 'q:orders.dlq'],
    ]);
    expect(graph).toMatchObject({
      aggregated: false,
      omitted: { nodes: 0, edges: 0 },
      focus: null,
      depth: null,
    });
    expect(output.gaps).toEqual([]);
    expect(output.snapshot).toMatchObject({
      consumers: 'read',
      truncation: { queues: 0, bindings: 0 },
    });
  });

  it('draws an alternate-exchange link from an argument', async () => {
    const { output } = await answerOf(
      { vhost: '/' },
      {
        '/': {
          exchanges: [
            { name: 'in', arguments: { 'alternate-exchange': 'ae' } },
            { name: 'ae', type: 'fanout' },
          ],
        },
      },
    );

    expect(output.graph.edges).toMatchObject([
      { kind: 'alternate-exchange', from: 'x:in', to: 'x:ae' },
    ]);
  });

  it('draws no dead-letter link it could not resolve, and says why', async () => {
    const { output } = await answerOf(
      { vhost: '/' },
      { '/': { ...SAMPLE_VHOST, policies: 'forbidden' } },
    );

    // The argument alone does not settle the routing key while the policies are unread: no link.
    expect(output.graph.edges.some((e) => e.kind === 'dead-letter')).toBe(
      false,
    );
    expect(output.gaps).toContain('policy-unreadable');
  });

  it('aggregates a vhost larger than the cap and counts what it folded', async () => {
    const queues = Array.from({ length: 300 }, (_, i) => ({
      name: `q${String(i)}`,
      policy: null,
      operator_policy: null,
    }));
    const { output } = await answerOf(
      { vhost: '/', maxElements: 50 },
      {
        '/': {
          exchanges: [{ name: 'fan', type: 'fanout' }],
          queues,
          bindings: queues.map((q) => ({ source: 'fan', destination: q.name })),
        },
      },
    );

    expect(output.graph.elements).toBeLessThanOrEqual(50);
    expect(output.graph.aggregated).toBe(true);
    expect(output.graph.totals).toMatchObject({ exchanges: 1, queues: 300 });
    expect(output.graph.omitted.nodes).toBeGreaterThan(200);
  });

  it('carries the cuts of the read in the answer', async () => {
    const { output } = await answerOf(
      { vhost: '/' },
      { '/': { queues: [{ name: 'a' }, { name: 'b' }, { name: 'c' }] } },
      { limits: { maxQueues: 2 } },
    );

    expect(output.snapshot.truncation.queues).toBe(1);
    expect(output.gaps).toContain('truncated');
    expect(output.graph.totals.queues).toBe(2);
  });
});
